/* =================================================================================================
   6hm — FONTS THE PDF DOES NOT ALREADY HAVE
   Ced: "add century gothic fonts and more fonts available."

   Every face the tool offered until now was one of the PDF's own standard fourteen — Helvetica,
   Times, Courier — because those need no embedding: the viewer already has them. Anything else has to
   travel inside the file, and a file that carries its own font is the only way a mark can look the
   same on a machine that has never heard of the face it is set in.

   So one geometric sans travels with the tool: JOST, an open face in the Century Gothic manner
   (Century Gothic itself is licensed and cannot be redistributed, and shipping a face we may not ship
   would be worse than not offering one at all). Four cuts — regular, bold, italic and bold italic —
   each subset to the characters a PDF string can hold, which is what keeps the whole family under a
   hundred kilobytes.

   The same bytes serve BOTH renderers: an `@font-face` gives the screen exactly the face the file
   carries, so the two agree glyph for glyph rather than approximately. That is worth more than the
   size: every other face in the list is a pair of metric-compatible cousins, and this one is one font.

   What follows is a small TrueType reader — `head`, `hhea`, `hmtx`, `cmap`, `post`, `OS/2` — and a
   writer for the PDF font dictionary it needs (a simple TrueType font with WinAnsi encoding, which
   is the encoding every string this tool writes is already restricted to). It exists so the tool does
   not have to carry a general font library for one family: the reader is a page of code, the library
   would be a third of a megabyte.
   ================================================================================================= */
const MA_TTF_B64={
"jost": "",
"jostbold": "",
"jostital": "",
"jostbolditalic": "",

  /* 6n1 — Ced: "add more font options." Two more families that travel with the file,
     subset and read exactly as Jost is. CARLITO is metric-compatible with Calibri, which is
     what the Word and Excel paperwork around these reports is set in, so a note written here
     and a line pasted out of the tracker look like the same document. ARCHIVO NARROW is a
     condensed grotesque: a corrected value that will not fit a table cell in Arial fits in
     this, which is the one thing a redliner runs out of room for. Both are OFL. */
  "carlito": "",
  "carlitobold": "",
  "carlitoital": "",
  "carlitobolditalic": "",
  "narrow": "",
  "narrowbold": "",
  "narrowital": "",
  "narrowbolditalic": ""
};

/* ---- the reader ------------------------------------------------------------------------------ */
function ttfBytes(key){
  const b64=MA_TTF_B64[key]; if(!b64)return null;
  const bin=atob(b64); const u=new Uint8Array(bin.length);
  for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);
  return u;
}
/* WinAnsi (cp1252) is Latin-1 except for the 0x80–0x9f band, which carries typographic characters
   rather than control codes. Only that band needs naming; everything else is its own code point. */
const WINANSI_HI={0x80:0x20ac,0x82:0x201a,0x83:0x0192,0x84:0x201e,0x85:0x2026,0x86:0x2020,
  0x87:0x2021,0x88:0x02c6,0x89:0x2030,0x8a:0x0160,0x8b:0x2039,0x8c:0x0152,0x8e:0x017d,
  0x91:0x2018,0x92:0x2019,0x93:0x201c,0x94:0x201d,0x95:0x2022,0x96:0x2013,0x97:0x2014,
  0x98:0x02dc,0x99:0x2122,0x9a:0x0161,0x9b:0x203a,0x9c:0x0153,0x9e:0x017e,0x9f:0x0178};
function winAnsiCode(b){ return (b>=0x80&&b<=0x9f)?(WINANSI_HI[b]||0):b; }

function ttfParse(u){
  const dv=new DataView(u.buffer,u.byteOffset,u.byteLength);
  const u16=o=>dv.getUint16(o), i16=o=>dv.getInt16(o), u32=o=>dv.getUint32(o);
  const numTables=u16(4), tab={};
  for(let i=0;i<numTables;i++){
    const o=12+i*16;
    const tag=String.fromCharCode(u[o],u[o+1],u[o+2],u[o+3]);
    tab[tag]={off:u32(o+8), len:u32(o+12)};
  }
  if(!tab.head||!tab.hhea||!tab.hmtx||!tab.cmap)return null;
  const head=tab.head.off;
  const unitsPerEm=u16(head+18)||1000;
  const bbox=[i16(head+36),i16(head+38),i16(head+40),i16(head+42)];
  const hhea=tab.hhea.off;
  const ascent=i16(hhea+4), descent=i16(hhea+6);
  const numH=u16(hhea+34);
  /* advance widths, per glyph; past `numH` every glyph keeps the last one */
  const hmtx=tab.hmtx.off;
  const adv=g=>u16(hmtx+((g<numH?g:numH-1)*4));
  /* the unicode cmap: format 4 is what a subset in this range always has */
  let sub=0;
  const cm=tab.cmap.off, n=u16(cm+2);
  for(let i=0;i<n;i++){
    const pid=u16(cm+4+i*8), eid=u16(cm+6+i*8), off=u32(cm+8+i*8);
    if((pid===3&&(eid===1||eid===0))||pid===0){ sub=cm+off; if(pid===3&&eid===1)break; }
  }
  let glyphOf=()=>0;
  if(sub&&u16(sub)===4){
    const segX2=u16(sub+6), seg=segX2/2;
    const ends=sub+14, starts=ends+segX2+2, deltas=starts+segX2, ranges=deltas+segX2;
    glyphOf=c=>{
      for(let i=0;i<seg;i++){
        if(u16(ends+i*2)>=c){
          const st=u16(starts+i*2); if(st>c)return 0;
          const ro=u16(ranges+i*2);
          if(!ro)return (c+i16(deltas+i*2))&0xffff;
          const gi=u16(ranges+i*2+ro+(c-st)*2);
          return gi?((gi+i16(deltas+i*2))&0xffff):0;
        }
      }
      return 0;
    };
  }
  const post=tab.post?tab.post.off:0;
  const italic=post?(dv.getInt32(post+4)/65536):0;
  const os2=tab["OS/2"]?tab["OS/2"].off:0;
  const cap=(os2&&tab["OS/2"].len>=70)?i16(os2+88):Math.round(ascent*0.7);
  return {unitsPerEm, bbox, ascent, descent, italic, cap, glyphOf, adv};
}
/* the width of one WinAnsi string, in POINTS at `size`, from the font's own metrics */
function ttfWidth(m,text,size){
  if(!m)return 0;
  let w=0; const s=String(text==null?"":text);
  for(let i=0;i<s.length;i++)w+=m.adv(m.glyphOf(s.charCodeAt(i)));
  return w*size/m.unitsPerEm;
}

/* ---- the writer ------------------------------------------------------------------------------ */
/* A simple TrueType font, WinAnsi-encoded, with the file itself in /FontFile2. Returns the same shape
   the standard fonts do — a `ref` to name in a resource dictionary and a width function — so nothing
   in the export has to know which kind of font it is holding. */
function ttfEmbed(PDFLib,doc,key,psName){
  const {PDFName,PDFNumber,PDFArray}=PDFLib;
  const u=ttfBytes(key); if(!u)return null;
  const m=ttfParse(u); if(!m)return null;
  const ctx=doc.context;
  const scale=1000/m.unitsPerEm;
  const file=ctx.flateStream?ctx.flateStream(u,{Length1:u.length})
                            :ctx.stream(u,{Length1:u.length});
  const fileRef=ctx.register(file);
  const flags=32|(m.italic?64:0);              /* nonsymbolic, and italic when it is */
  const desc=ctx.obj({
    Type:"FontDescriptor", FontName:PDFName.of(psName), Flags:flags,
    FontBBox:ctx.obj(m.bbox.map(v=>Math.round(v*scale))),
    ItalicAngle:Math.round(m.italic*100)/100,
    Ascent:Math.round(m.ascent*scale), Descent:Math.round(m.descent*scale),
    CapHeight:Math.round(m.cap*scale), StemV:80, FontFile2:fileRef
  });
  const descRef=ctx.register(desc);
  const widths=[];
  for(let b=32;b<=255;b++){
    const cp=winAnsiCode(b);
    widths.push(cp?Math.round(m.adv(m.glyphOf(cp))*scale):0);
  }
  const font=ctx.obj({
    Type:"Font", Subtype:"TrueType", BaseFont:PDFName.of(psName),
    FirstChar:32, LastChar:255, Widths:ctx.obj(widths),
    Encoding:PDFName.of("WinAnsiEncoding"), FontDescriptor:descRef
  });
  const ref=ctx.register(font);
  return { ref, _ttf:true, widthOfTextAtSize:(t,s)=>ttfWidth(m,t,s) };
}

/* ---- and the same bytes on screen --------------------------------------------------------------
   Injected once, at boot. The face names are the ones `MARK_FONTS` asks for, so a mark set in Jost is
   laid out on screen with the very file the export embeds. */
/* 6n1 — every bundled cut, and the screen face it installs as: key, family, weight, style. */
const MA_TTF_FACES=[
  ["jost",            "MA Jost",   "400","normal"],
  ["jostbold",        "MA Jost",   "700","normal"],
  ["jostital",        "MA Jost",   "400","italic"],
  ["jostbolditalic",  "MA Jost",   "700","italic"],
  ["carlito",         "MA Carlito","400","normal"],
  ["carlitobold",     "MA Carlito","700","normal"],
  ["carlitoital",     "MA Carlito","400","italic"],
  ["carlitobolditalic","MA Carlito","700","italic"],
  ["narrow",          "MA Narrow", "400","normal"],
  ["narrowbold",      "MA Narrow", "700","normal"],
  ["narrowital",      "MA Narrow", "400","italic"],
  ["narrowbolditalic","MA Narrow", "700","italic"]
];
let _ttfFacesIn=false;
function ttfInstallFaces(){
  if(_ttfFacesIn)return; _ttfFacesIn=true;
  try{
    /* 6n1 — the family is part of the row now rather than a constant in the template, so adding a
       bundled family is one line here and one line in MARK_FONTS, and the two cannot disagree about
       what the face is called. */
    const css=MA_TTF_FACES.map(([k,fam,w,st])=>
      `@font-face{font-family:'${fam}';font-weight:${w};font-style:${st};font-display:block;`+
      `src:url(data:font/ttf;base64,${MA_TTF_B64[k]}) format('truetype')}`).join("\n");
    const el=document.createElement("style"); el.id="ttfFaces"; el.textContent=css;
    document.head.appendChild(el);
  }catch(e){ LOG&&LOG("bundled faces could not be installed",e&&e.message); }
}
